\title{Connected Components Govern the $L^p$ Threshold for Pattern Counts in Locally Dense Graphs}
\author{Aristotle}
\date{\today}

\begin{document}

\begin{abstract}
We study an $L^p$ relaxation of the classical multiplicative lower bound for pattern (homomorphism) counts in $\rho$-locally dense hosts, working throughout in the finite step-graphon model, where every integral is a genuine finite average and all statements are exact. A widely appealing conjecture predicts that, for a pattern graph $F$ with $m$ edges and $n$ non-isolated vertices, a locally dense counterexample to the bound $\|W_F\|_{L^p} \ge \rho^{\ecard(F)}$ exists whenever $p < \binom{n}{2}/m$. We prove that this literal threshold is false. First, for the single edge the threshold is exactly $p^\star = 1 = \binom{2}{2}/1$: no counterexample exists for $p\ge 1$ (a power-mean inequality), and an explicit block construction is a counterexample for $0<p<1$. Second, for the $2$-edge matching $M_2$ (with $n=4$, $m=2$, hence conjectured threshold $3$) the functional factorizes, $\|W_{M_2}\|_{L^p} = \|W_{K_2}\|_{L^p}^2$, and consequently no counterexample exists for any $p\ge 1$; the true threshold is $1$, not $3$, with unbounded gap over the matching family. We then isolate the reason: a bijection identifying edge-constant vertex colorings with arbitrary colorings of connected components shows block-kernel constructions reach the value $(n-c)/m$, where $c$ is the number of connected components of $F$, and no further. This yields the closed form $\sum_{\varphi} \prod_{\text{edges}} W(\varphi) = t^{D} k^{c}$ for block-diagonal kernels, exhibiting the component count $c$ as the exact exponent controlling the analytic size of the functional. Since $n - c \le \binom{n}{2}$ with unbounded slack, the conjectured threshold systematically overshoots.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{Locally dense hosts and the KNRS lower bound}
A \emph{graphon} is a symmetric measurable kernel $W$ with values in $[0,1]$. We work in the \textbf{finite step-graphon model}: the host is the finite set $[N]=\{0,\dots,N-1\}$ with the uniform probability measure, and $W\colon [N]^2\to[0,1]$ is symmetric. Every integral below is a finite average and every statement is an exact identity or inequality.

A graphon $W$ is \textbf{$\rho$-locally dense} (at level $\rho\in[0,1]$) if
\begin{equation}\label{eq:LD}
\frac{1}{|S|^2}\sum_{x,y\in S} W(x,y) \;\ge\; \rho \qquad \text{for every nonempty } S\subseteq [N]. \tag{LD}
\end{equation}
For a pattern graph $F$ with $n$ non-isolated vertices, edge set $E(F)$ of size $m=\ecard(F)$, the \emph{$L^p$ pattern functional} is
\[
\|W_F\|_{L^p} = \left( \frac{1}{N^{n}} \sum_{\varphi\colon V(F)\to [N]} \prod_{\{u,v\}\in E(F)} W(\varphi(u),\varphi(v))^{p} \right)^{1/p}.
\]
The classical Kohayakawa--Nagle--R\"odl--Schacht (KNRS) lower bound states $\|W_F\|_{L^1} \ge \rho^{\ecard(F)}$ for $\rho$-locally dense hosts.

\subsection{The suspect threshold}
\begin{conjecture}[suspect form]
For $F$ with $m$ edges and $n$ non-isolated vertices, if $p < \binom{n}{2}/m$ then there is a $\rho$-locally dense $W$ with $\|W_F\|_{L^p} < \rho^{\ecard(F)}$.
\end{conjecture}
The ratio $\binom{n}{2}/m$ is memorable, but we show it is incorrect.

\section{Preliminaries}
Write $[k]=\{0,\dots,k-1\}$ for block indices. For a finite simple graph $G$, $c(G)$ is the number of connected components and $D(G)=|\{(a,b):a\sim b\}|=2\,\ecard(G)$ the number of directed edges. We use the averaged \textbf{power-mean inequality}: for nonnegative $a_1,\dots,a_M$ and $p\ge1$,
\begin{equation}\label{eq:PM}
\Big(\tfrac1M\textstyle\sum_i a_i\Big)^{p} \le \tfrac1M\textstyle\sum_i a_i^{p}. \tag{PM}
\end{equation}

\section{The single edge: threshold exactly $1$}
For $F=K_2$, $\|W_{K_2}\|_{L^p} = \big(\tfrac{1}{N^2}\sum_{x,y}W(x,y)^p\big)^{1/p}$.

\begin{theorem}[single-edge lower bound]\label{thm:single}
For every $p\ge1$ and every $\rho$-locally dense $W$ with values in $[0,1]$, $\|W_{K_2}\|_{L^p}\ge\rho$.
\end{theorem}
\begin{proof}
By \eqref{eq:PM} applied to the $N^2$ numbers $W(x,y)$ and then \eqref{eq:LD} with $S=[N]$,
$\|W_{K_2}\|_{L^p}^p = \tfrac1{N^2}\sum_{x,y}W(x,y)^p \ge \big(\tfrac1{N^2}\sum_{x,y}W(x,y)\big)^p \ge \rho^p$.
Take $p$-th roots.
\end{proof}

\begin{theorem}[block counterexample below $1$]\label{thm:blockedge}
Fix $k\ge2$ and let $W$ be the $k$-block graphon with $\beta(i,j)=\mathbf1[i=j]$. Then $W$ is $\rho$-locally dense with $\rho=1/k$, and for every $0<p<1$, $\|W_{K_2}\|_{L^p} = (1/k)^{1/p} < 1/k = \rho$.
\end{theorem}
\begin{proof}
For $S$ with in-block fractions $s_i$ ($\sum_i s_i=1$), $\tfrac1{|S|^2}\sum_{S\times S}W = \sum_i s_i^2 \ge (\sum_i s_i)^2/k = 1/k$, giving \eqref{eq:LD}. Since $W\in\{0,1\}$, $W^p=W$ and the same-block ordered-pair fraction is $k(1/k)^2=1/k$, so $\|W_{K_2}\|_{L^p}=(1/k)^{1/p}$. As $1/p>1$ and $1/k<1$, this is $<1/k$.
\end{proof}

\begin{theorem}[sharp single-edge threshold]\label{thm:sharpedge}
$p^\star(K_2) = 1 = \binom{2}{2}/1$: no counterexample for $p\ge1$, a counterexample for every $0<p<1$.
\end{theorem}
\begin{proof}
Combine Theorems~\ref{thm:single} and \ref{thm:blockedge}.
\end{proof}

\section{The $2$-edge matching: the conjecture fails}
Let $M_2$ have edges $\{1,2\},\{3,4\}$, so $n=4$, $m=2$, $c=2$; the conjectured threshold is $\binom{4}{2}/2=3$.

\begin{theorem}[factorization]\label{thm:factor}
For every $W$ and every $p>0$, $\|W_{M_2}\|_{L^p} = \|W_{K_2}\|_{L^p}^{2}$.
\end{theorem}
\begin{proof}
The disjoint edges make the sum factor:
$\|W_{M_2}\|_{L^p}^p = \tfrac1{N^4}\sum_{a,b,c,d}W(a,b)^pW(c,d)^p = \big(\tfrac1{N^2}\sum_{a,b}W(a,b)^p\big)^2 = (\|W_{K_2}\|_{L^p}^p)^2$.
\end{proof}

\begin{theorem}[no counterexample for $p\ge1$]\label{thm:matchnoce}
For every $p\ge1$ and every $\rho$-locally dense nonnegative $W$, $\|W_{M_2}\|_{L^p}\ge\rho^2 = \rho^{\ecard(M_2)}$.
\end{theorem}
\begin{proof}
By Theorems~\ref{thm:factor} and \ref{thm:single}, $\|W_{M_2}\|_{L^p}=\|W_{K_2}\|_{L^p}^2\ge\rho^2$.
\end{proof}

\begin{corollary}[the conjecture is false]\label{cor:false}
The threshold $\binom{n}{2}/m$ is incorrect: for $M_2$ it predicts counterexamples on $1\le p<3$, but none exist there. Through the factorization the block construction gives, for $0<p<1$, $\|W_{M_2}\|_{L^p}=(1/k)^{2/p}<(1/k)^2=\rho^2$. Hence $p^\star(M_2)=1$.
\end{corollary}

\begin{remark}[unbounded error]
For the $m$-edge matching, $n=2m$, $c=m$, true threshold $1$, while the conjecture predicts $\binom{2m}{2}/m=2m-1$; the gap $\to\infty$.
\end{remark}

\section{The mechanism: components as an exponent}
Fix a finite simple graph $G$ on $V$ and a palette $\beta$. A coloring $f\colon V\to\beta$ is \emph{edge-constant} if $f(a)=f(b)$ whenever $a\sim b$.

\begin{lemma}[edge-constant is walk-constant]\label{lem:walk}
If $f$ is edge-constant then $f(v)=f(w)$ whenever $v,w$ are connected.
\end{lemma}
\begin{proof}
Induction on walk length: the empty walk is trivial, and $v\sim v'$ with $f(v')=f(w)$ gives $f(v)=f(v')=f(w)$.
\end{proof}

\begin{theorem}[connector bijection]\label{thm:bij}
Edge-constant colorings of $V$ are in canonical bijection with maps $\Comp(G)\to\beta$.
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:walk} an edge-constant $f$ descends to $\bar f\colon\Comp(G)\to\beta$; conversely $g\mapsto (v\mapsto g([v]))$ is edge-constant. These are mutually inverse.
\end{proof}

\begin{corollary}[counting form]\label{cor:count}
$\#\{f\colon V\to[k]\mid f \text{ edge-constant}\} = k^{c(G)}$.
\end{corollary}

Let $W_t(i,j)=t\,\mathbf1[i=j]$ and $\homf(W_t,\varphi)=\prod_{a}\prod_{b}\big(\text{if }a\sim b\text{ then }W_t(\varphi a,\varphi b)\text{ else }1\big)$.

\begin{lemma}[collapse to an indicator]\label{lem:collapse}
$\homf(W_t,\varphi) = t^{D(G)}$ if $\varphi$ is edge-constant, and $0$ otherwise.
\end{lemma}
\begin{proof}
If edge-constant, each of the $D(G)$ edge factors equals $t$. Otherwise some edge factor is $W_t(\varphi a,\varphi b)=0$.
\end{proof}

\begin{theorem}[block-kernel closed form]\label{thm:closed}
$\displaystyle\sum_{\varphi\colon V\to[k]}\homf(W_t,\varphi) = t^{D(G)}\,k^{c(G)}$.
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:collapse} only edge-constant $\varphi$ contribute $t^{D(G)}$; by Corollary~\ref{cor:count} there are $k^{c(G)}$ of them.
\end{proof}

\section{From the closed form to the corrected threshold}
Normalizing Theorem~\ref{thm:closed} with $D=2m$, on-diagonal weight $\rho k$, kernel raised to the $p$-th power ($t=(\rho k)^p$), and dividing by $k^n$ gives
\[
\|W_F\|_{L^p}^{p} = k^{\,c-n+mp}\,\rho^{\,mp},
\]
so $\|W_F\|_{L^p} < \rho^{m}$ for large $k$ iff $c-n+mp<0$, i.e.\ $p < (n-c)/m$.

\begin{theorem}[corrected reachable threshold]\label{thm:corrected}
For every finite $F$ with $n$ vertices, $m$ edges, $c$ components, block-diagonal constructions give a $\rho$-locally dense counterexample for every $p<(n-c)/m$.
\end{theorem}

\begin{corollary}[consistency]\label{cor:consist}
$(n-c)/m$ gives $1$ for $K_2$, $1$ for $M_2$, $1$ for all matchings, and always $(n-c)/m\le\binom{n}{2}/m$; for matchings the slack is unbounded.
\end{corollary}

\section{Discussion and future work}
The magnitude of the $L^p$ pattern integral for block hosts is controlled by the number of connected components of the pattern, an instance of ``counting pieces controls an integral.'' The case $p=1$ recovers the KNRS bound and links the threshold question to Sidorenko's conjecture. Open directions:
\begin{enumerate}
\item Determine the exact $p^\star(F)$; is it $(n-c)/m$ for all $F$? First test: the triangle $K_3$ ($n=3,m=3,c=1$, block bound $2/3$).
\item Rank-one PSD perturbations $W=\rho+c\,\varphi(x)\varphi(y)$ (automatically locally dense) as candidates to beat $(n-c)/m$.
\item A normalized general block-kernel theorem $\|W_F\|_{L^p}^p = k^{c-n+mp}\rho^{mp}$.
\item A continuum bridge to genuine graphons on $[0,1]^2$.
\item An undirected (Sym2) edge model reconciling directed and undirected edge counts.
\end{enumerate}

\end{document}

