from typing import Callable

Kernel = Callable[[int, int], float]

def single_edge_lp(W: Kernel, N: int, p: float) -> float:
    total = sum(W(x, y) ** p for x in range(N) for y in range(N))
    return (total / (N * N)) ** (1.0 / p)

def block_kernel_01(k: int):
    def W(x: int, y: int) -> float:
        return 1.0 if x == y else 0.0
    return W, k, 1.0 / k

def demo() -> None:
    k = 4
    W, N, rho = block_kernel_01(k)
    for p in [0.25, 0.5, 0.75, 1.0, 1.5, 2.0, 4.0]:
        val = single_edge_lp(W, N, p)
        verdict = 'counterexample' if val < rho else 'bound holds'
        print(f'p={p:>4}  ||W_K2||_Lp={val:.6f}  rho={rho}  {verdict}')

if __name__ == '__main__':
    demo()

from typing import Callable

Kernel = Callable[[int, int], float]

def single_edge_lp(W: Kernel, N: int, p: float) -> float:
    return (sum(W(x, y) ** p for x in range(N) for y in range(N)) / N**2) ** (1/p)

def matching_lp(W: Kernel, N: int, p: float) -> float:
    total = sum((W(a,b)**p)*(W(c,d)**p)
                for a in range(N) for b in range(N)
                for c in range(N) for d in range(N))
    return (total / N**4) ** (1/p)

def demo() -> None:
    k = 3
    W = lambda x, y: 1.0 if x == y else 0.0
    N, rho = k, 1.0 / k
    for p in [0.5, 1.0, 2.0, 2.9]:
        direct = matching_lp(W, N, p)
        factor = single_edge_lp(W, N, p) ** 2
        verdict = 'counterexample' if direct < rho**2 else 'bound holds'
        print(f'p={p}: direct={direct:.6f} factor={factor:.6f} '
              f'rho^2={rho**2:.4f} {verdict}')

if __name__ == '__main__':
    demo()

from itertools import product
from typing import List, Tuple

def num_components(nv: int, edges: List[Tuple[int, int]]) -> int:
    parent = list(range(nv))
    def find(a: int) -> int:
        while parent[a] != a:
            parent[a] = parent[parent[a]]; a = parent[a]
        return a
    for a, b in edges:
        parent[find(a)] = find(b)
    return len({find(i) for i in range(nv)})

def brute(nv: int, edges: List[Tuple[int, int]], k: int, t: float) -> float:
    directed = edges + [(v, u) for (u, v) in edges]
    total = 0.0
    for phi in product(range(k), repeat=nv):
        prod = 1.0
        for a, b in directed:
            prod *= t if phi[a] == phi[b] else 0.0
        total += prod
    return total

def demo() -> None:
    k, t = 3, 2.0
    patterns = {'K2': (2, [(0,1)]), 'M2': (4, [(0,1),(2,3)]),
                'P3': (3, [(0,1),(1,2)]), 'K3': (3, [(0,1),(1,2),(0,2)])}
    for name, (nv, edges) in patterns.items():
        c = num_components(nv, edges); D = 2 * len(edges)
        print(f'{name}: brute={brute(nv,edges,k,t):.0f} '
              f'closed={(t**D)*(k**c):.0f} (c={c}, D={D})')

if __name__ == '__main__':
    demo()

