function COMPONENTS(n, edges):
    parent[i] <- i  for i in 0..n-1
    function FIND(a):
        while parent[a] != a:
            parent[a] <- parent[parent[a]]   # path compression
            a <- parent[a]
        return a
    for (a,b) in edges:
        ra, rb <- FIND(a), FIND(b)
        if ra != rb: parent[ra] <- rb
    return |{ FIND(i) : i in 0..n-1 }|

