function COMPARE_THRESHOLDS(n, edges):
    m <- |edges|
    c <- COMPONENTS(n, edges)
    corrected  <- (n - c) / m
    conjectured <- (n*(n-1)/2) / m
    return (corrected, conjectured, conjectured - corrected)

